// S3-03 - Preparar recomendacion de venta
// Mode: Run Once for All Items

const filas = $input.all()
  .map(i => i.json)
  .filter(r => r.producto && r.precio_actual != null);

const fuente = $('Switch1').first().json;

const clase = typeof fuente.output === 'string'
  ? JSON.parse(fuente.output)
  : (fuente.output ?? fuente);

const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);

const buscado = clase.producto ?? null;

const num = v =>
  v === null || v === undefined || v === ''
    ? null
    : (Number.isFinite(Number(v)) ? Number(v) : null);

const normal = s => String(s ?? '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const razones = [];

function resumen(d) {
  return {
    producto: d.producto,
    unidad: d.unidad,

    fecha_ultimo_registro: d.fecha_ultimo_registro,

    precio_actual: num(d.precio_actual),
    precio_anterior: num(d.precio_anterior),
    precio_promedio_7: num(d.precio_promedio_7),
    precio_promedio_30: num(d.precio_promedio_30),

    tendencia_precio: d.tendencia_precio,

    fecha_ultimo_volumen: d.fecha_ultimo_volumen,
    volumen_ultimo_t: num(d.volumen_ultimo_t),
    volumen_actual_t: num(d.volumen_actual_t),
    volumen_promedio_7_t: num(d.volumen_promedio_7_t),
    volumen_promedio_30_t: num(d.volumen_promedio_30_t),

    registros_precio_7: num(d.registros_precio_7) ?? 0,
    registros_volumen_7: num(d.registros_volumen_7) ?? 0,

    total_registros_precio:
      num(d.total_registros_precio) ?? 0,

    total_registros_volumen:
      num(d.total_registros_volumen) ?? 0,

    dias_desde_precio: num(d.dias_desde_precio),

    desfase_precio_volumen_dias:
      num(d.desfase_precio_volumen_dias),

    desde: d.desde,
    hasta: d.hasta
  };
}

const lista = filas.map(resumen);

// CONSULTA GENERAL DEL MERCADO
if (!buscado) {
  return [{
    json: {
      modo: 'general',
      pregunta_usuario: pregunta,
      mercado: 'GMML',
      productos_analizados: lista.length,
      resumen_mercado: lista,
      estado_recomendacion: 'no_aplica',
      instrucciones:
        'Describir los productos analizados. ' +
        'No recomendar una accion de venta ' +
        'para todo el mercado.'
    }
  }];
}

// IDENTIFICAR PRODUCTO Y VARIEDAD

// SELECCIONAR PRODUCTO Y PRESENTACION COMERCIAL

const textoPregunta = normal(pregunta);

// Detectar si el usuario solicito una unidad especifica
let unidadPedida = null;

if (/\batados?\b/.test(textoPregunta)) {
  unidadPedida = 'atado';
} else if (/\bdocenas?\b/.test(textoPregunta)) {
  unidadPedida = 'docena';
} else if (/\b(kilogramos?|kilos?|kg)\b/.test(textoPregunta)) {
  unidadPedida = 'kilogramo';
}

// Buscar primero coincidencias exactas del producto
const exactos = lista.filter(
  r => normal(r.producto) === normal(buscado)
);

// Si no hay coincidencia exacta, buscar por nombre
const candidatos = exactos.length
  ? exactos
  : lista.filter(
      r => normal(r.producto).includes(normal(buscado))
    );

// Filtrar por la unidad solicitada, si existe
let seleccionados = unidadPedida
  ? candidatos.filter(
      r => normal(r.unidad) === unidadPedida
    )
  : candidatos;

// Cuando no se indica unidad, priorizar kilogramo
// solamente si existe una unica coincidencia
let seleccionAutomatica = false;

if (!unidadPedida && seleccionados.length > 1) {
  const enKilogramos = seleccionados.filter(
    r => normal(r.unidad) === 'kilogramo'
  );

  if (enKilogramos.length === 1) {
    seleccionados = enKilogramos;
    seleccionAutomatica = true;
  }
}

// Solo hay ambiguedad si quedan varias presentaciones
const ambiguo = seleccionados.length > 1;

// No escoger arbitrariamente la primera fila
const d = seleccionados.length === 1
  ? seleccionados[0]
  : null;


// CRITERIOS DE DATOS SUFICIENTES

if (!d && seleccionados.length === 0) {
  razones.push(
    'No se encontraron registros de precios para el producto y presentacion solicitados.'
  );
}

if (ambiguo) {
  razones.push(
    'La consulta agrupa varias variedades o ' +
    'presentaciones. Se necesita una variedad ' +
    'y unidad especificas.'
  );
}

if (d && !ambiguo) {
  if (d.registros_precio_7 < 5) {
    razones.push(
      'Hay menos de 5 registros recientes de precio.'
    );
  }

  if (d.registros_volumen_7 < 3) {
    razones.push(
      'Hay menos de 3 registros de volumen para comparar.'
    );
  }

  if (
    d.precio_anterior === null ||
    d.precio_promedio_7 === null ||
    d.precio_promedio_7 <= 0 ||
    d.precio_actual <= 0
  ) {
    razones.push(
      'No existe una comparacion reciente de precios valida.'
    );
  }

  if (
    d.volumen_ultimo_t === null ||
    d.volumen_promedio_7_t === null ||
    d.volumen_promedio_7_t <= 0
  ) {
    razones.push(
      'Falta volumen reciente o su promedio comparable.'
    );
  }

  if (
    d.dias_desde_precio === null ||
    d.dias_desde_precio > 7
  ) {
    razones.push(
      'El ultimo precio tiene mas de 7 dias de antiguedad.'
    );
  }

  if (
    d.desfase_precio_volumen_dias === null ||
    d.desfase_precio_volumen_dias > 7
  ) {
    razones.push(
      'La fecha del ultimo volumen esta demasiado ' +
      'alejada de la fecha del precio.'
    );
  }
}

const suficiente = Boolean(
  d && !ambiguo && razones.length === 0
);

let decision = null;
let razones_decision = [];

// REGLAS DE DECISION DEL PROTOTIPO
if (suficiente) {
  const relacionPrecio =
    d.precio_actual / d.precio_promedio_7;

  const relacionVolumen =
    d.volumen_ultimo_t / d.volumen_promedio_7_t;

  if (
    relacionPrecio >= 1.05 &&
    relacionVolumen <= 0.90
  ) {
    decision = 'Vender ahora';

  } else if (
    relacionPrecio <= 0.95 &&
    relacionVolumen >= 1.10
  ) {
    decision = 'Esperar y monitorear';

  } else {
    decision = 'Vender parcialmente y monitorear';
  }

  razones_decision = [
    `Precio: S/ ${d.precio_actual} por ${d.unidad}, ` +
    `promedio de 7 registros: S/ ${d.precio_promedio_7}.`,

    `Ultimo volumen: ${d.volumen_ultimo_t} t ` +
    `(${d.fecha_ultimo_volumen}), ` +
    `promedio de 7 registros: ${d.volumen_promedio_7_t} t.`,

    `Tendencia entre los dos ultimos precios: ` +
    d.tendencia_precio
  ];
}

return [{
  json: {
    modo: 'especifico',
    pregunta_usuario: pregunta,
    producto_solicitado: buscado,
    mercado: 'GMML',

    datos: ambiguo ? null : d,

    coincidencias: ambiguo
      ? candidatos.map(x => ({
          producto: x.producto,
          unidad: x.unidad
        }))
      : [],

    estado_recomendacion:
      suficiente ? 'suficiente' : 'insuficiente',

    faltantes: razones,

    decision_sugerida: decision,
    razones_decision,

    criterio_minimo:
      '5 precios, 3 volumenes, antiguedad maxima ' +
      'de 7 dias y fechas comparables.',

    unidad_seleccionada: d?.unidad ?? null,
    unidad_seleccionada_por_defecto: seleccionAutomatica,

    nota:
      'El clima no fue incluido en esta ejecucion.'
  }
}];

