// 1. Traemos el clima y los precios usando la sintaxis moderna
const satelite = $('HTTP Request open meteo1').first().json; 
const precios = $input.all();

// 2. Traemos de forma segura lo que entendió la primera IA
const texto_primera_ia = $('Switch1').first().json.output;
const datos_usuario = JSON.parse(texto_primera_ia);

// 3. Armamos el reporte completo incluyendo el producto y la ciudad
const reporte = `
CONTEXTO DE LA CONSULTA:
- Producto a evaluar: ${datos_usuario.producto}
- Ubicación: ${datos_usuario.lugar}

DATOS DEL CLIMA (Open-Meteo):
${JSON.stringify(satelite.daily)}

HISTORIAL DE PRECIOS (Últimos 7 días):
${JSON.stringify(precios)}
`;

return { prompt_final: reporte };

const respuesta = $input.first().json;

const vector = respuesta.data?.[0]?.embedding;

if (!Array.isArray(vector) || vector.length === 0) {
  throw new Error(
    'No se pudo obtener el embedding de Jina AI'
  );
}

if (vector.length !== 384) {
  throw new Error(
    `Dimensión inesperada: ${vector.length}. Se esperaban 384 dimensiones.`
  );
}

return [{
  json: {
    dimension: vector.length,
    embedding: `[${vector.join(',')}]`
  }
}];

// AGROSMART - CONTEXTO RAG + DATOS SQL

const filas = $input.all().map(item => item.json);

// Obtener la clasificacion utilizada por Switch1
let clasificacion = {};

try {
  const salida = $('Switch1').first().json.output;

  clasificacion = typeof salida === 'string'
    ? JSON.parse(salida)
    : (salida ?? {});

} catch (error) {
  throw new Error(
    'No se pudo leer la clasificacion: ' + error.message
  );
}

// Pregunta y filtros
const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);

const producto =
  clasificacion.producto ??
  filas[0]?.producto_solicitado ??
  null;

const fecha =
  clasificacion.fecha ??
  filas[0]?.fecha_solicitada ??
  null;

// Normalizar texto para buscar productos
function normalizar(texto) {
  return String(texto ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}

// Extraer partes del documento relacionadas
// con el producto solicitado
function extractosRelevantes(texto, termino) {
  const contenido = String(texto ?? '');

  if (!termino) {
    return contenido.length > 1050
      ? contenido.slice(0, 1050) + ' […]'
      : contenido;
  }

  const simple = normalizar(contenido);
  const buscado = normalizar(termino).trim();

  if (!buscado) {
    return contenido.slice(0, 1050);
  }

  const ventanas = [];
  let desde = 0;
  let ultimoFin = 0;

  while (ventanas.length < 5) {
    const inicio = simple.indexOf(buscado, desde);

    if (inicio === -1) break;

    const a = Math.max(0, inicio - 110);
    const b = Math.min(
      contenido.length,
      inicio + buscado.length + 300
    );

    if (b > ultimoFin) {
      ventanas.push(
        contenido.slice(Math.max(a, ultimoFin), b)
      );

      ultimoFin = b;
    }

    desde = inicio + buscado.length;
  }

  return ventanas.join('\n[…]\n');
}

// Filtrar documentos validos
const documentos = filas.filter(f =>
  f.id != null &&
  typeof f.text === 'string' &&
  f.text.trim()
);

// Construir contexto documental
const secciones = documentos.map((f, i) => {
  let metadata = f.metadata ?? {};

  if (typeof metadata === 'string') {
    try {
      metadata = JSON.parse(metadata);
    } catch (_) {
      metadata = {};
    }
  }

  const fuente =
    metadata.filename ||
    metadata.archivo ||
    metadata.fuente ||
    'Boletin MIDAGRI - GMML';

  const fechaDocumento =
    metadata.fecha ||
    metadata.date ||
    'Fecha no especificada';

  const contenido = extractosRelevantes(
    f.text,
    producto
  );

  if (!contenido.trim()) return null;

  return `
DOCUMENTO ${i + 1}

FUENTE: ${fuente}
FECHA_METADATA: ${fechaDocumento}

FRAGMENTO RELACIONADO CON ${producto ?? 'LA PREGUNTA'}:
${contenido}
`;
}).filter(Boolean);

// Recuperar precios estructurados
let precios = filas[0]?.datos_precios ?? [];

if (typeof precios === 'string') {
  try {
    precios = JSON.parse(precios);
  } catch (_) {
    precios = [];
  }
}

if (!Array.isArray(precios)) {
  precios = [];
}

// Formatear datos SQL sin inventar valores
const registros = precios.slice(0, 25).map(p => {
  const volumen = p.volumen_t == null
    ? ''
    : `; volumen_t=${p.volumen_t}`;

  const equivalencia = p.equivalencia_kg == null
    ? ''
    : `; equivalencia_kg=${p.equivalencia_kg}`;

  return (
    `- ${p.fecha} | ${p.producto}: ` +
    `S/ ${p.precio} por ${p.unidad}` +
    volumen +
    equivalencia
  );
});

// Construir contexto final
const contexto = [
  `CONSULTA:
Producto: ${producto ?? 'no especificado'}
Fecha: ${fecha ?? 'sin fecha especifica'}`,

  `DATOS ESTRUCTURADOS DE PRECIOS_DIARIOS (GMML):

${registros.length
  ? registros.join('\n')
  : 'No se encontraron precios estructurados para esta fecha y producto, o no se solicito una fecha concreta.'}`,

  `FRAGMENTOS DE BOLETINES MIDAGRI:

${secciones.length
  ? secciones.join('\n-------------------\n')
  : 'No se encontraron fragmentos con coincidencia de producto y fecha en los metadatos.'}`
].join('\n\n');

// Devolver contexto para Basic LLM Chain2
return [{
  json: {
    pregunta_usuario: pregunta,
    producto_solicitado: producto,
    fecha_solicitada: fecha,
    documentos_recuperados: secciones.length,
    precios_recuperados: precios.length,
    contexto
  }
}];

// AgroSmart WF2 - Code conversion a toneladas
// Modo: Run Once for All Items
// Diferencia subtotal con datos vs. total general no verificado.

const filas = $input.all().map(item => item.json ?? {});

const entrada = $('Switch1').first().json;
const clasificacion = typeof entrada.output === 'string'
  ? JSON.parse(entrada.output)
  : (entrada.output ?? entrada);

const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);

function numero(valor) {
  if (valor === null || valor === undefined || valor === '') return null;
  const n = Number(valor);
  return Number.isFinite(n) && n >= 0 ? n : null;
}

function redondear(valor, decimales = 3) {
  return Number(valor.toFixed(decimales));
}

const registros = filas
  .filter(f => f.producto != null)
  .map(f => {
    const tOriginal = numero(f.volumen_t);
    const kgOriginal = numero(f.volumen_kg_almacenado);

    const toneladas = tOriginal !== null
      ? tOriginal
      : (kgOriginal !== null ? kgOriginal / 1000 : null);

    const inconsistencia = tOriginal !== null && kgOriginal !== null
      && Math.abs(kgOriginal - tOriginal * 1000) > 1;

    return {
      fecha: f.fecha_consultada ?? null,
      producto: f.producto,
      unidad: f.unidad ?? null,
      equivalencia_kg: numero(f.equivalencia_kg),
      precio: numero(f.precio),
      volumen_t: toneladas === null ? null : redondear(toneladas),
      volumen_kg: toneladas === null ? null : redondear(toneladas * 1000),
      tiene_volumen: toneladas !== null,
      advertencia_volumen: inconsistencia
        ? 'volumen_t y volumen_kg almacenados no coinciden'
        : null
    };
  });

const conDato = registros.filter(r => r.tiene_volumen);
const sinDato = registros.filter(r => !r.tiene_volumen);

// COUNT(*) OVER() de la consulta SQL, repetido en sus filas.
const totalCoincidencias = numero(
  filas.find(f => f.total_coincidencias != null)?.total_coincidencias
) ?? 0;

const consultaLimitada = totalCoincidencias > registros.length;

const sumaDisponible = conDato.length > 0
  ? conDato.reduce((acc, r) => acc + r.volumen_t, 0)
  : null;

const subtotalT = sumaDisponible === null
  ? null
  : redondear(sumaDisponible);

const subtotalKg = sumaDisponible === null
  ? null
  : redondear(sumaDisponible * 1000);

const advertencias = registros
  .filter(r => r.advertencia_volumen)
  .map(r => `${r.producto}: ${r.advertencia_volumen}`);

return [{
  json: {
    pregunta_usuario: pregunta,
    producto_solicitado: clasificacion.producto ?? null,

    fecha_consultada:
      filas[0]?.fecha_consultada ??
      clasificacion.fecha ??
      null,

    consulta_historica:
      filas[0]?.consulta_historica === true ||
      (
        filas[0]?.consulta_historica == null &&
        clasificacion.fecha != null
      ),

    mercado: 'GMML',
    registros,

    registros_recuperados: registros.length,
    registros_con_volumen: conDato.length,
    registros_sin_volumen: sinDato.length,

    productos_sin_volumen:
      sinDato.map(r => r.producto),

    filas_coincidentes_en_bd: totalCoincidencias,
    consulta_limitada: consultaLimitada,

    subtotal_volumen_registrado_t: subtotalT,
    subtotal_volumen_registrado_kg: subtotalKg,

    // Nunca afirmar que el subtotal es el total oficial.
    total_general_verificado: false,

    cobertura_registros: registros.length === 0
      ? 'sin_registros'
      : (sinDato.length > 0 || consultaLimitada)
        ? 'parcial'
        : 'registros_recuperados_con_volumen',

    advertencias,
    sin_datos: registros.length === 0,

    regla_para_responder:
      'El subtotal suma exclusivamente las filas con volumen numérico. ' +
      'No es un total general verificado frente al consolidado oficial. ' +
      'Indicar filas faltantes y no inventar sus valores.'
  }
}];

/*
 AgroSmart WF2
 Comparación de precios GMML y MMF2
 Fecha consultada + dos registros anteriores
*/

const filas = $input.all()
  .map(x => x.json)
  .filter(x => x.producto && x.precio != null);

// Clasificación de la consulta
const raw = $('Switch1').first().json.output;

const clase = typeof raw === 'string'
  ? JSON.parse(raw)
  : (raw ?? {});

const pregunta = String(
  $('Webhook').first().json.body?.pregunta ?? ''
);

const producto = clase.producto ?? 'el producto solicitado';

const referencia = filas[0]?.fecha_consultada ??
  clase.fecha ??
  new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Lima',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(new Date());

const historica = Boolean(clase.fecha);

const meses = [
  'enero', 'febrero', 'marzo', 'abril',
  'mayo', 'junio', 'julio', 'agosto',
  'septiembre', 'octubre', 'noviembre',
  'diciembre'
];

function fechaBonita(valor) {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(
    String(valor ?? '')
  );

  if (!m) return 'fecha no disponible';

  return `${Number(m[3])} de ${
    meses[Number(m[2]) - 1]
  } de ${m[1]}`;
}

function dinero(valor) {
  return `S/ ${Number(valor).toLocaleString('es-PE', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  })}`;
}

function normalizar(valor) {
  return String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

// Agrupar por producto y presentación
const grupos = new Map();

for (const r of filas) {
  const clave = [
    normalizar(r.producto),
    normalizar(r.unidad)
  ].join('|');

  if (!grupos.has(clave)) {
    grupos.set(clave, {
      producto: r.producto,
      unidad: r.unidad,
      registros: []
    });
  }

  grupos.get(clave).registros.push(r);
}

const variedades = [...grupos.values()]
  .sort((a, b) =>
    a.producto.localeCompare(b.producto, 'es')
  );

// Sin resultados
if (variedades.length === 0) {
  return [{
    json: {
      respuesta:
        `No encontré precios de ${producto} ` +
        `en GMML ni MMF2 hasta el ` +
        `${fechaBonita(referencia)}.`
    }
  }];
}

const lineas = [];

lineas.push(
  historica
    ? `Precios de ${producto} — ${fechaBonita(referencia)}`
    : `Precios disponibles de ${producto} — consulta del ${fechaBonita(referencia)}`
);

const mercados = ['GMML', 'MMF2'];

if (variedades.length > 5) {
  lineas.push(
    `Se muestran 5 de ${variedades.length} variedades o presentaciones.`
  );
}

for (const variedad of variedades.slice(0, 5)) {

  lineas.push(
    `\n${variedad.producto} — ${variedad.unidad}`
  );

  for (const mercado of mercados) {

    const registros = variedad.registros
      .filter(r => r.mercado === mercado)
      .sort((a, b) =>
        Number(a.dias_atras) - Number(b.dias_atras)
      );

    if (registros.length === 0) {
      lineas.push(
        `• ${mercado}: sin registros disponibles.`
      );
      continue;
    }

    const principal = registros[0];

    const coincide =
      principal.fecha === referencia;

    if (historica && !coincide) {
      lineas.push(
        `• ${mercado}: no hay precio registrado ` +
        `el ${fechaBonita(referencia)}.`
      );

      lineas.push(
        `  Último precio anterior: ` +
        `${dinero(principal.precio)} ` +
        `por ${variedad.unidad} ` +
        `(${fechaBonita(principal.fecha)}).`
      );

    } else {

      const etiqueta = historica
        ? 'Precio registrado'
        : coincide
          ? 'Precio de hoy'
          : 'Último precio disponible';

      lineas.push(
        `• ${mercado}: ${etiqueta}: ` +
        `${dinero(principal.precio)} ` +
