// ==========================================
// PREPARAR ERROR PARA LANGFUSE
// ==========================================

function hexAleatorio(bytes) {
  let resultado = '';

  for (let i = 0; i < bytes; i++) {
    resultado += Math
      .floor(Math.random() * 256)
      .toString(16)
      .padStart(2, '0');
  }

  return resultado;
}


// ==========================================
