// AGROSMART - NORMALIZAR CLASIFICACION
// Corrige respuestas con ```json y JSON normal

function extraerObjeto(valor) {

  if (
    valor !== null &&
    typeof valor === 'object' &&
    !Array.isArray(valor)
  ) {
    return valor;
  }

  if (
    typeof valor !== 'string' ||
    !valor.trim()
  ) {
    throw new Error(
      'La salida del agente esta vacia o no es JSON.'
    );
  }

  let texto = valor.trim().replace(/^\uFEFF/, '');

  // Eliminar bloques Markdown ```json ... ```
  const bloque = texto.match(
    /```(?:json)?\s*([\s\S]*?)\s*```/i
  );

  if (bloque) {
    texto = bloque[1].trim();
  } else if (!texto.startsWith('{')) {

    // Buscar el objeto si el agente agrega un prefacio
    const inicio = texto.indexOf('{');
    const fin = texto.lastIndexOf('}');

    if (inicio >= 0 && fin > inicio) {
      texto = texto.slice(inicio, fin + 1);
    }
  }

  let datos;

  try {
    datos = JSON.parse(texto);
  } catch (error) {
    throw new Error(
      'El agente no genero JSON valido: ' +
      error.message +
      '. Salida: ' +
      texto.slice(0, 150)
    );
  }

  if (
    !datos ||
    typeof datos !== 'object' ||
    Array.isArray(datos)
  ) {
    throw new Error(
      'La clasificacion debe ser un objeto JSON.'
    );
  }

  const categorias = [
    'precio_puntual',
    'volumen_ingreso',
    'tendencia_prediccion',
    'clima',
    'analisis_satelital_riesgo',
    'general',
    'fuera_alcance'
  ];

  if (!categorias.includes(datos.tipo_consulta)) {
    throw new Error(
      'tipo_consulta no valido: ' +
      String(datos.tipo_consulta)
    );
  }

  if (
    datos.fecha != null &&
    !/^\d{4}-\d{2}-\d{2}$/.test(datos.fecha)
  ) {
    throw new Error(
      'La fecha debe ser YYYY-MM-DD o null.'
    );
  }

  return datos;
}

// Procesar todos los items
return $input.all().map(item => {

  const datos = extraerObjeto(
    item.json.output ?? item.json.text
  );

  return {
    json: {
      ...item.json,

      // Mantener compatibilidad con tus nodos
      // que utilizan JSON.parse($json.output)
      output: JSON.stringify(datos),

      producto: datos.producto ?? null,
      periodo: datos.periodo ?? null,
      fecha: datos.fecha ?? null,
      tipo_consulta: datos.tipo_consulta,
      lugar: datos.lugar ?? null
    }
  };
});

// AgroSmart S3-03 - Respuesta final para el agricultor
// Nodo: Code - Validar recomendacion S3-03
// Modo: Run Once for All Items

const e = $('Code in JavaScript2').first().json;
const modelo = String($input.first()?.json?.text ?? $input.first()?.json?.output ?? '').trim();

function num(valor) {
  if (valor === null || valor === undefined || valor === '') return null;
  const n = Number(valor);
  return Number.isFinite(n) ? n : null;
}

function nf(valor, max = 2, min = 2) {
  const n = num(valor);
  return n === null ? 'sin dato' : n.toLocaleString('es-PE', {
    minimumFractionDigits: min,
    maximumFractionDigits: max
  });
}

function fechaEs(valor) {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(valor ?? ''));
  if (!m) return 'fecha no disponible';

  const meses = [
    'enero','febrero','marzo','abril','mayo','junio',
    'julio','agosto','septiembre','octubre','noviembre','diciembre'
  ];

  const mes = Number(m[2]);
  if (mes < 1 || mes > 12) return 'fecha no disponible';

  return `${Number(m[3])} de ${meses[mes - 1]} de ${m[1]}`;
}

function relacion(actual, promedio) {
  const a = num(actual);
  const b = num(promedio);

  if (a === null || b === null || b <= 0) {
    return 'No hay comparación disponible.';
  }

  if (Math.abs(a - b) < 0.00001) {
    return 'Está al nivel de su promedio.';
  }

  return `Está ${a > b ? 'por encima' : 'por debajo'} de su promedio.`;
}

// Consultas generales de mercado
if (e.modo !== 'especifico') {
  return [{
    json: {
      text: modelo || 'No se pudo generar el resumen general.',
      estado_recomendacion: e.estado_recomendacion ?? 'no_aplica'
    }
  }];
}

const d = e.datos ?? null;

const producto =
  e.producto_solicitado ||
  d?.producto ||
  'el producto solicitado';

const permitidas = new Set([
  'Vender ahora',
  'Esperar y monitorear',
  'Vender parcialmente y monitorear'
]);

const suficiente =
  e.estado_recomendacion === 'suficiente' &&
  d !== null &&
  permitidas.has(e.decision_sugerida);

const lineas = [
  `Evaluación comercial de ${producto} — GMML`
];

// Mostrar primero la recomendacion
lineas.push(
  suficiente
    ? `\nRECOMENDACIÓN: ${e.decision_sugerida.toUpperCase()}`
    : '\nRECOMENDACIÓN: DATOS INSUFICIENTES'
);

// Mostrar los indicadores disponibles
if (d) {
  lineas.push(
    `\nÚltimo precio: S/ ${nf(d.precio_actual)} por ${d.unidad || 'unidad no indicada'} (${fechaEs(d.fecha_ultimo_registro)}).`,

    `Promedio de 7 registros de precio: S/ ${nf(d.precio_promedio_7)}; promedio de 30: S/ ${nf(d.precio_promedio_30)}. ${relacion(d.precio_actual, d.precio_promedio_7)}`,

    `\nÚltimo volumen registrado: ${nf(d.volumen_ultimo_t, 3, 0)} toneladas (${fechaEs(d.fecha_ultimo_volumen)}).`,

    `Promedio de 7 registros de volumen: ${nf(d.volumen_promedio_7_t, 3, 0)} toneladas; promedio de 30: ${nf(d.volumen_promedio_30_t, 3, 0)}. ${relacion(d.volumen_ultimo_t, d.volumen_promedio_7_t)}`
  );

  const tendencia = {
    alza: 'subió',
    baja: 'bajó',
    estable: 'se mantuvo'
  }[d.tendencia_precio];

  if (tendencia) {
    lineas.push(
      `Respecto del precio anterior (S/ ${nf(d.precio_anterior)}), el precio ${tendencia}.`
    );
  }
}

// Escenario 1: informacion suficiente
if (suficiente) {
  lineas.push('\n¿Por qué esta recomendación?');

  if (e.decision_sugerida === 'Esperar y monitorear') {
    lineas.push(
      'El precio está relativamente débil y/o la oferta es elevada según los indicadores analizados. Esto no garantiza una recuperación futura.'
    );

    lineas.push(
      '\n¿Qué significa esperar y monitorear?',
      '• Revisar el siguiente boletín disponible de MIDAGRI y comprobar si el precio cambia.',
      '• Observar si disminuye o aumenta el volumen que ingresa al mercado.',
      '• Comparar el costo de conservar la cosecha con el precio que ofrecen los compradores. Si no es viable esperar, evaluar una venta parcial.'
    );

  } else if (e.decision_sugerida === 'Vender ahora') {
    lineas.push(
      'Las reglas del prototipo identifican señales favorables para comercializar con los indicadores disponibles.'
    );

    lineas.push(
      '\n¿Qué puedes hacer ahora?',
      '• Pedir cotizaciones a compradores y comparar el precio neto ofrecido.',
      '• Revisar transporte, comisiones y otros costos antes de confirmar la venta.',
      '• Verificar el próximo boletín para detectar cambios en precio y abastecimiento.'
    );

  } else {
    lineas.push(
      'Los indicadores no dan una señal suficientemente clara para vender todo o esperar con toda la cosecha.'
    );

    lineas.push(
      '\n¿Qué puedes hacer ahora?',
      '• Evaluar vender una parte para obtener liquidez, según tus necesidades.',
      '• Revisar precios y volúmenes en los próximos boletines.',
      '• Considerar el estado del producto y el costo de guardar el resto.'
    );
  }

// Escenario 2: informacion insuficiente
} else {
  lineas.push(
    '\nNo es posible emitir una recomendación de venta sólida con los datos disponibles.'
  );

  const faltantes = Array.isArray(e.faltantes)
    ? e.faltantes
    : [];

  if (faltantes.length) {
    lineas.push('\n¿Qué falta para recomendar?');

    for (const motivo of faltantes) {
      lineas.push(`• ${String(motivo)}`);
    }
  }

  if (
    Array.isArray(e.coincidencias) &&
    e.coincidencias.length
  ) {
    lineas.push(
      'Presentaciones disponibles: ' +
      e.coincidencias
        .map(x => `${x.producto} (${x.unidad})`)
        .join(', ') + '.'
    );
  }

  lineas.push(
    'Revisa el boletín más reciente y considera los costos de conservación antes de decidir.'
  );
}

// Cierre de la respuesta
lineas.push(
  '\nEsta evaluación es orientativa y se basa en los registros disponibles en AgroSmart; no garantiza precios futuros.'
);

return [{
  json: {
    text: lineas.join('\n'),
    estado_recomendacion: e.estado_recomendacion ?? null
  }
}];
